        "edits": {
          "annotation:F01": {
            "base": {
              "summary": "按角色名称和状态查询当前站点角色。"
            },
            "values": {
              "summary": ""
            }
          },
          "annotation:T01": {
            "base": {
              "summary": "展示当前站点已创建的角色和使用情况。",
              "rules": [
                "字段为序号、角色名称、角色说明、状态、关联账号、更新时间、操作；列表与汇总不拆分权限，统一使用【查看列表】。",
                "站点主账号为系统内置角色，不允许编辑、停用、删除或复制；自定义角色可编辑权限并启用或停用。",
                "停用角色后，关联账号立即失去该角色权限，角色配置和历史授权记录保留。",
                "表格仅在内容超出对应可视区域时显示滚动条：横向滚动条高度、纵向滚动条宽度均保持15px；内容可完整显示时对应滚动条隐藏"
              ]
            },
            "values": {
              "summary": "",
              "rules": [
                "站点主账号为系统内置角色，不允许编辑、停用、删除或复制；自定义角色可编辑权限并启用或停用。",
                "停用角色后，关联账号也自动停用，账号登录时提示账号被停用。",
                "表格仅在内容超出对应可视区域时显示滚动条：横向滚动条高度、纵向滚动条宽度均保持15px；内容可完整显示时对应滚动条隐藏"
              ]
            }
          },
          "annotation:B01": {
            "base": {
              "summary": "创建一个新的站点自定义角色。"
            },
            "values": {
              "summary": ""
            }
          },
          "annotation:M01": {
            "base": {
              "summary": "维护角色基础信息和业务权限。",
              "rules": [
                "权限树按会员管理、运营数据看板、财务管理、运营报表、代理模块、合营配置、活动管理分组。",
                "业务页面默认权限为【查看列表】，其他操作权限单独勾选；没有独立操作权限的页面在子权限栏显示【全部权限】。未勾选默认权限时，其他操作不可选，取消默认权限时同步清空该页面操作权限。运营数据看板只提供一个整体权限，不展示子权限。",
                "不提供数据范围选择；所有自定义角色默认拥有当前站点全部数据的访问范围，权限树仅决定可访问的页面和操作。",
                "会员列表的默认权限包含会员详情；【查看存款/场馆/投注明细】统一控制三类明细。彩票会员返水报表的【查看代理返水佣金】同时控制代理返水佣金页签及其明细，不单列【查看明细】。",
                "平台财务管理的默认权限包含流水详情；【内部转账给会员】与【内部转账给代理】分别授权。代理佣金结算的默认权限包含运营费明细；佣金报表的默认权限包含账单明细；财务报表的默认权限包含费用明细。",
                "全站转账明细的默认权限包含收款方明细；三方场馆代理费用明细的默认权限包含场馆费明细。",
                "代理列表的默认权限包含代理关系、下级代理及下级会员查看，不单列【查看代理详情】；【代理信息修改操作】统一控制修改、启用/停用、修改登录密码和重置取款密码，新增与导出仍单独授权。冲正统计报表仅保留页面默认权限，不单列明细权限。",
                "负盈利代理佣金结算的默认权限包含费用明细，子权限仅有【发放佣金】和【导出】；【发放佣金】同时包含发放、不发放和修改发放。负盈利代理佣金报表的默认权限包含会员及费用明细，子权限仅有【导出】。",
                "团队代理管理的默认权限包含团队详情；合营配置用【修改合营配置】统一控制新增联系方式、编辑、删除及开启/关闭显示；活动列表的默认权限包含活动详情。",
                "系统管理及其下级页面在弹窗内以不可授权状态展示，不提供复选框。",
                "保存时校验角色名称必填和同站点唯一；取消或关闭不保存修改。"
              ]
            },
            "values": {
              "summary": "",
              "rules": [
                "弹窗类权限限制时，交互为：提示无权限\n菜单类权限限制时，交互为：隐藏菜单\n操作类权限限制时，交互为：隐藏操作按钮/文字/选项",
                "未勾选默认权限时，其他操作不可选，取消默认权限时同步清空该页面操作权限。",
                "全站转账明细的默认权限包含收款方明细；三方场馆代理费用明细的默认权限包含场馆费明细。",
                "代理列表的【代理信息修改操作】统一控制：修改、启用/停用、修改登录密码和重置取款密码",
                "负盈利代理佣金结算的【发放佣金】同时包含：发放、不发放和修改发放。",
                "合营配置用【修改合营配置】统一控制：新增联系方式、编辑、删除、开启/关闭显示；",
                "保存时校验角色名称必填和同站点唯一；"
              ]
            }
          },
          "annotation:B02": {
            "base": {
              "rules": [
                "停用前弹窗说明会立即影响关联账号；确认后角色状态变为停用，重新启用后恢复原权限。",
                "系统内置站点主账号不提供停用入口。"
              ]
            },
            "values": {
              "rules": [
                "停用前弹窗说明会立即禁止登录关联账号；确认后角色状态变为停用，重新启用后恢复原权限。",
                "系统内置站点主账号不提供停用入口。"
              ]
            }
          },
          "annotation:N01": {
            "base": {
              "summary": "在系统管理中新增角色管理能力。",
              "rules": [
                "【角色管理】位于站点后台【系统管理】菜单下，仅站点最高权限账号可以进入、创建和维护角色。",
                "系统管理及其下级页面不进入角色授权树，不能授权给任何自定义角色；普通账号直接访问页面或接口也必须被拒绝。",
                "可授权业务范围以站点后台 RBAC 权限树为准，共 25 个业务页面；所有角色默认可访问当前站点全部数据，不配置更细的数据范围。"
              ]
            },
            "values": {
              "summary": "",
              "rules": [
                "【系统管理】及其下级页面不进入角色授权树，不能授权给任何自定义角色；普通账号直接访问页面或接口也必须被拒绝。只有系统账号可访问和查看"
              ]
            }
          }
        },
